To implement a function that finds the shortest path in a weighted graph, we can use Dijkstra's algorithm. Dijkstra's algorithm works well for graphs with non-negative edge weights. Here's a simple implementation of Dijkstra's algorithm in Python:

```python
import heapq
from collections import defaultdict

def dijkstra(graph, start):
    """
    Finds the shortest path from the start node to all other nodes in a weighted graph.

    :param graph: A dictionary representing the weighted graph. The keys are node labels,
                  and the values are dictionaries that map neighboring nodes to their edge weights.
    :param start: The starting node.
    :return: A dictionary containing the shortest distance from the start node to all other nodes.
             It also contains the shortest path tree, which is a dictionary mapping each node to its parent in the shortest path tree.
    """
    # Priority queue to store (distance, node) pairs.
    priority_queue = []
    heapq.heappush(priority_queue, (0, start))
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    previous_nodes = {node: None for node in graph}
    shortest_path_tree = {}

    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)

        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph[current_node].items():
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                previous_nodes[neighbor] = current_node
                heapq.heappush(priority_queue, (distance, neighbor))
                shortest_path_tree[neighbor] = current_node

    return distances, previous_nodes, shortest_path_tree

# Example usage
if __name__ == "__main__":
    graph = {
        'A': {'B': 1, 'C': 4},
        'B': {'A': 1, 'C': 2, 'D': 5},
        'C': {'A': 4, 'B': 2, 'D': 1},
        'D': {'B': 5, 'C': 1}
    }

    start_node = 'A'
    distances, previous_nodes, shortest_path_tree = dijkstra(graph, start_node)

    print("Shortest distances from node", start_node, "to all other nodes:")
    for node, dist in distances.items():
        print(f"{start_node} -> {node}: {dist}")

    print("\nShortest path tree:")
    for node, parent in shortest_path_tree.items():
        if parent is not None:
            print(f"{start_node} -> {node}: {parent}")
